import { VercelRequest, VercelResponse } from '@vercel/node';

export default async function handler(req: VercelRequest, res: VercelResponse) {
    // Enable CORS for both Chrome extension and browser testing
    const origin = req.headers.origin;
    if (origin) {
        if (origin.startsWith('chrome-extension://') || origin === 'https://lummi-extension.vercel.app') {
            res.setHeader('Access-Control-Allow-Origin', origin);
        }
    } else {
        // For testing directly in the browser
        res.setHeader('Access-Control-Allow-Origin', '*');
    }
    res.setHeader('Access-Control-Allow-Methods', 'GET, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');

    // Handle preflight requests
    if (req.method === 'OPTIONS') {
        return res.status(200).end();
    }

    try {
        const { query } = req.query;
        console.log('Received query:', query);

        if (!query || typeof query !== 'string') {
            return res.status(400).json({ error: 'Query parameter is required' });
        }

        const LUMMI_API_KEY = process.env.LUMMI_API_KEY;
        if (!LUMMI_API_KEY) {
            console.error('API key not found in environment variables');
            return res.status(500).json({ error: 'API key not configured' });
        }

        console.log('Making request to Lummi API...');
        const apiUrl = `https://api.lummi.ai/v1/images?query=${encodeURIComponent(query)}`;
        console.log('Request URL:', apiUrl);

        const response = await fetch(apiUrl, {
            headers: {
                'Authorization': `Bearer ${LUMMI_API_KEY}`,
                'Content-Type': 'application/json',
            },
        });

        if (!response.ok) {
            const errorText = await response.text();
            console.error('Lummi API error:', response.status, errorText);
            return res.status(response.status).json({
                error: 'Lummi API error',
                status: response.status,
                details: errorText
            });
        }

        const data = await response.json();
        console.log('Successfully received response from Lummi API');
        return res.status(200).json(data);
    } catch (error) {
        console.error('Error proxying request:', error);
        return res.status(500).json({
            error: 'Failed to fetch images',
            details: error instanceof Error ? error.message : 'Unknown error'
        });
    }
}

import { VercelRequest, VercelResponse } from '@vercel/node';
import fetch from 'node-fetch';
import * as cheerio from 'cheerio';

const CLIENT_ID = '1idqPQHGdjsMFy8NwQT';
const ICON_SIZE = 400;

function cleanDomain(url: string): string {
    const domain = new URL(url).hostname;
    // Remove www. prefix if present
    return domain.replace(/^www\./, '');
}

async function getBrandfetchIcon(domain: string): Promise<string | null> {
    try {
        // Use direct CDN URL with size parameters
        const cdnUrl = `https://cdn.brandfetch.io/${domain}/w/${ICON_SIZE}/h/${ICON_SIZE}?c=${CLIENT_ID}`;
        console.log('Trying Brandfetch CDN:', cdnUrl);
        const response = await fetch(cdnUrl);
        if (response.ok) {
            return cdnUrl;
        }

        // If that fails, try Clearbit as backup
        const clearbitUrl = `https://logo.clearbit.com/${domain}`;
        console.log('Trying Clearbit CDN:', clearbitUrl);
        const clearbitResponse = await fetch(clearbitUrl);
        if (clearbitResponse.ok) {
            return clearbitUrl;
        }

        console.log('All logo attempts failed for:', domain);
        return null;
    } catch (error) {
        console.error('Error fetching icon:', error);
        return null;
    }
}

async function getFallbackIcon(url: string): Promise<string | null> {
    try {
        const response = await fetch(url);
        const html = await response.text();
        const $ = cheerio.load(html);

        // Try apple-touch-icon first (usually highest quality)
        const appleTouchIcon = $('link[rel="apple-touch-icon"]').attr('href') ||
            $('link[rel="apple-touch-icon-precomposed"]').attr('href');
        if (appleTouchIcon) {
            const iconUrl = new URL(appleTouchIcon, url).href;
            console.log('Found apple-touch-icon:', iconUrl);
            const iconResponse = await fetch(iconUrl);
            if (iconResponse.ok) {
                return iconUrl;
            }
        }

        // Try regular favicon
        const favicon = $('link[rel="icon"]').attr('href') ||
            $('link[rel="shortcut icon"]').attr('href');
        if (favicon) {
            const iconUrl = new URL(favicon, url).href;
            console.log('Found favicon:', iconUrl);
            const iconResponse = await fetch(iconUrl);
            if (iconResponse.ok) {
                return iconUrl;
            }
        }

        // Try default favicon.ico
        const defaultFavicon = new URL('/favicon.ico', url).href;
        console.log('Trying default favicon:', defaultFavicon);
        const defaultResponse = await fetch(defaultFavicon);
        if (defaultResponse.ok) {
            return defaultFavicon;
        }

        return null;
    } catch (error) {
        console.error('Error fetching fallback icon:', error);
        return null;
    }
}

export default async function handler(req: VercelRequest, res: VercelResponse) {
    // Enable CORS
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'GET, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

    if (req.method === 'OPTIONS') {
        return res.status(200).end();
    }

    const { url } = req.query;

    if (!url || typeof url !== 'string') {
        return res.status(400).json({ error: 'URL is required' });
    }

    try {
        // Clean the domain for icon fetching
        const domain = cleanDomain(url);
        console.log('Fetching icon for domain:', domain);

        // Try Brandfetch first
        const brandfetchIcon = await getBrandfetchIcon(domain);
        if (brandfetchIcon) {
            console.log('Found Brandfetch icon:', brandfetchIcon);
            return res.status(200).json({
                title: domain,
                icon: brandfetchIcon
            });
        }

        // If Brandfetch fails, try fallback methods
        console.log('Brandfetch failed, trying fallback methods');
        const fallbackIcon = await getFallbackIcon(url);

        return res.status(200).json({
            title: domain,
            icon: fallbackIcon || null
        });
    } catch (error) {
        console.error('Error fetching metadata:', error);
        return res.status(500).json({ error: 'Failed to fetch metadata' });
    }
}

import { VercelRequest, VercelResponse } from '@vercel/node';

export default async function handler(req: VercelRequest, res: VercelResponse) {
    // Enable CORS
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'GET, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization, Accept');
    res.setHeader('Content-Type', 'application/json');

    // Handle preflight request
    if (req.method === 'OPTIONS') {
        res.status(200).end();
        return;
    }

    const { query } = req.query;

    if (!query) {
        return res.status(400).json({ error: 'Query parameter is required' });
    }

    try {
        // Check if API key is available
        const apiKey = process.env.LUMMI_API_KEY;
        if (!apiKey) {
            console.error('LUMMI_API_KEY is not defined in environment variables');
            return res.status(500).json({
                error: 'Server configuration error',
                details: 'API key is missing'
            });
        }

        console.log('Making search request for query:', query);
        const apiUrl = `https://api.lummi.ai/v1/images/search?query=${encodeURIComponent(query as string)}&orientation=horizontal`;
        console.log('Using Lummi API URL:', apiUrl);

        const response = await fetch(apiUrl, {
            headers: {
                'Authorization': `Bearer ${apiKey}`,
                'Accept': 'application/json',
                'Content-Type': 'application/json'
            }
        });

        if (!response.ok) {
            const errorText = await response.text();
            console.error('Lummi API error:', {
                status: response.status,
                body: errorText
            });
            return res.status(response.status).json({
                error: 'Lummi API error',
                status: response.status,
                details: errorText
            });
        }

        const contentType = response.headers.get('content-type');
        if (!contentType?.includes('application/json')) {
            const text = await response.text();
            console.error('Non-JSON response from Lummi API:', {
                contentType,
                text: text.substring(0, 200)
            });
            return res.status(500).json({
                error: 'Invalid response from Lummi API',
                details: 'Response was not JSON'
            });
        }

        const data = await response.json();

        // Validate the response structure
        if (!data || !Array.isArray(data.data)) {
            console.error('Invalid response structure from Lummi API:', data);
            return res.status(500).json({
                error: 'Invalid response structure',
                details: 'Response did not contain valid data array'
            });
        }

        console.log('Received response from Lummi API:', {
            query,
            totalResults: data.data.length
        });

        return res.status(200).json(data);
    } catch (error) {
        console.error('Error in search handler:', error);
        return res.status(500).json({
            error: 'Internal server error',
            details: error instanceof Error ? error.message : 'Unknown error'
        });
    }
}

